import type { StockPhoto } from '@aglyn/aglyn/plugin-manager/stock-photo-provider'

/**
 * PIXABAY'S RECORDED ANSWERS FOR THE BETA.266 MEXICANO PORTFOLIO START
 * (AGL-3923, job C75nFALn3H, host 7R9loxHdfa, 2026-10-18 16:52Z): the seven
 * searches its home page sent, every one new to the cache, written
 * 16:54:36-38Z. Read back from production's `stockPhotoSearches` by each
 * search's key (a SHA-256 of the provider and the request's canonical
 * parameters), never searched again. Ids, sizes, page slugs and tags are
 * Pixabay's own, in its order; the contributor is left out.
 */

const hit = (id: number, width: number, height: number, slug: string, tags: string): StockPhoto =>
  ({
    provider: 'pixabay',
    id: String(id),
    width,
    height,
    pageUrl: `https://pixabay.com/photos/${slug}/`,
    photographer: 'A Pixabay contributor',
    tags: tags ? tags.split(', ') : [],
    downloadUrl: `https://pixabay.com/get/g${id}_1280.jpg`,
  }) as StockPhoto

